using Microsoft.EntityFrameworkCore; using Screenings.Database; using Screenings.Domain;
namespace Screenings.Services;
public sealed class ScreeningService(ScreeningsDbContext db):IScreeningService{public async Task<IReadOnlyList<ScreeningResponseDto>> GetAsync(DateOnly? date,CancellationToken token){var query=db.Screenings.AsNoTracking();if(date.HasValue){var start=date.Value.ToDateTime(TimeOnly.MinValue,DateTimeKind.Utc);query=query.Where(x=>x.StartsAtUtc>=start&&x.StartsAtUtc<start.AddDays(1));}return await query.OrderBy(x=>x.StartsAtUtc).Select(x=>Map(x)).ToListAsync(token);}public async Task<bool> HasOverlapAsync(Guid hallId,DateTime start,DateTime end,Guid? excludedId,CancellationToken token)=>await db.Screenings.AnyAsync(x=>x.HallId==hallId&&x.Status!=ScreeningStatus.Cancelled&&(!excludedId.HasValue||x.Id!=excludedId.Value)&&x.StartsAtUtc<end&&x.EndsAtUtc>start,token);public async Task<ScreeningResponseDto> CreateAsync(CreateScreeningRequestDto r,CancellationToken t){var s=new Screening{Id=Guid.NewGuid(),MovieId=r.MovieId,HallId=r.HallId,StartsAtUtc=r.StartsAtUtc,EndsAtUtc=r.EndsAtUtc,BaseTicketPrice=r.BaseTicketPrice};db.Screenings.Add(s);await db.SaveChangesAsync(t);return Map(s);}public async Task<ScreeningResponseDto?> UpdateAsync(Guid id,UpdateScreeningRequestDto r,CancellationToken t){var s=await db.Screenings.FirstOrDefaultAsync(x=>x.Id==id,t);if(s is null)return null;s.MovieId=r.MovieId;s.HallId=r.HallId;s.StartsAtUtc=r.StartsAtUtc;s.EndsAtUtc=r.EndsAtUtc;s.BaseTicketPrice=r.BaseTicketPrice;s.Status=r.Status;await db.SaveChangesAsync(t);return Map(s);}public async Task<bool> DeleteAsync(Guid id,CancellationToken t){var s=await db.Screenings.FirstOrDefaultAsync(x=>x.Id==id,t);if(s is null)return false;db.Screenings.Remove(s);await db.SaveChangesAsync(t);return true;}private static ScreeningResponseDto Map(Screening s)=>new(){Id=s.Id,MovieId=s.MovieId,HallId=s.HallId,StartsAtUtc=s.StartsAtUtc,EndsAtUtc=s.EndsAtUtc,BaseTicketPrice=s.BaseTicketPrice,Status=s.Status};}
